class Solution {
    public int splitArray(int[] nums, int k) {
        int left = 0;
        int right = 0;
        for (int num : nums) {
            left = Math.max(left, num);
            right += num;
        }

        while (left < right) {
            int mid = left + (right - left) / 2;
            if (canSplit(nums, k, mid)) {
                right = mid;
            } else {
                left = mid + 1;
            }
        }
        return left;
    }

    private boolean canSplit(int[] nums, int k, int limit) {
        int groups = 1;
        int sum = 0;
        for (int num : nums) {
            if (sum + num > limit) {
                groups++;
                sum = 0;
                if (groups > k) {
                    return false;
                }
            }
            sum += num;
        }
        return true;
    }
}

class Solution {
    public int splitArray(int[] nums, int k) {
        int left = 0;
        int right = 0;
        for (int num : nums) {
            left = Math.max(left, num);
            right += num;
        }

        int answer = right;
        while (left <= right) {
            int mid = left + (right - left) / 2;
            int groups = groupsNeeded(nums, mid);
            if (groups <= k) {
                answer = mid;
                right = mid - 1;
            } else {
                left = mid + 1;
            }
        }
        return answer;
    }

    private int groupsNeeded(int[] nums, int limit) {
        int groups = 1;
        int sum = 0;
        for (int num : nums) {
            if (sum + num > limit) {
                groups++;
                sum = 0;
            }
            sum += num;
        }
        return groups;
    }
}

class Solution {
    public int splitArray(int[] nums, int k) {
        int n = nums.length;
        int[] prefix = new int[n + 1];
        for (int i = 0; i < n; i++) {
            prefix[i + 1] = prefix[i] + nums[i];
        }

        int[][] dp = new int[n + 1][k + 1];
        for (int[] row : dp) {
            Arrays.fill(row, Integer.MAX_VALUE);
        }
        dp[0][0] = 0;

        for (int parts = 1; parts <= k; parts++) {
            for (int i = parts; i <= n; i++) {
                for (int cut = parts - 1; cut < i; cut++) {
                    if (dp[cut][parts - 1] == Integer.MAX_VALUE) {
                        continue;
                    }
                    int lastSum = prefix[i] - prefix[cut];
                    int largest = Math.max(dp[cut][parts - 1], lastSum);
                    dp[i][parts] = Math.min(dp[i][parts], largest);
                }
            }
        }
        return dp[n][k];
    }
}

class Solution {
    private int[] nums;
    private int[] prefix;
    private int[][] memo;

    public int splitArray(int[] nums, int k) {
        this.nums = nums;
        int n = nums.length;
        prefix = new int[n + 1];
        for (int i = 0; i < n; i++) {
            prefix[i + 1] = prefix[i] + nums[i];
        }

        memo = new int[n][k + 1];
        for (int[] row : memo) {
            Arrays.fill(row, -1);
        }
        return solve(0, k);
    }

    private int solve(int index, int parts) {
        int n = nums.length;
        if (parts == 1) {
            return prefix[n] - prefix[index];
        }
        if (memo[index][parts] != -1) {
            return memo[index][parts];
        }

        int best = Integer.MAX_VALUE;
        for (int next = index + 1; next <= n - parts + 1; next++) {
            int firstSum = prefix[next] - prefix[index];
            if (firstSum >= best) {
                break;
            }
            int remaining = solve(next, parts - 1);
            best = Math.min(best, Math.max(firstSum, remaining));
        }
        memo[index][parts] = best;
        return best;
    }
}
